CREATE TABLE IF NOT EXISTS cards (id TEXT PRIMARY KEY, title TEXT NOT NULL, body TEXT NOT NULL, summary TEXT, url TEXT, type TEXT NOT NULL DEFAULT 'memo', color TEXT, tags_json JSONB NOT NULL DEFAULT '[]', links_json JSONB NOT NULL DEFAULT '[]', kj_group_id TEXT, archived BOOLEAN NOT NULL DEFAULT FALSE, archived_at TIMESTAMPTZ, tokens_json JSONB NOT NULL DEFAULT '[]', doc_length INTEGER NOT NULL DEFAULT 0, created_at TIMESTAMPTZ NOT NULL, updated_at TIMESTAMPTZ NOT NULL);
CREATE INDEX IF NOT EXISTS idx_cards_created_at ON cards(created_at);
CREATE INDEX IF NOT EXISTS idx_cards_type ON cards(type);
